// src/components/AdminStudentsFees.jsx
import React, { useEffect, useState } from "react";
import axios from "axios";
import toast, { Toaster } from "react-hot-toast";
import { FontAwesomeIcon } from "@fortawesome/react-fontawesome";
import { faTrash } from "@fortawesome/free-solid-svg-icons";
import "../styles/main.css";

export default function AdminStudentsFees() {
  const [students, setStudents] = useState([]);
  const [selected, setSelected] = useState(null);
  const [feeData, setFeeData] = useState({}); // merged defaults + overrides
  const [paid, setPaid] = useState(0);
  const [total, setTotal] = useState(0);
  const [remaining, setRemaining] = useState(0);

  // DEFAULT class-based structure (Option A)
  const getClassDefaults = (cls) => {
    const c = Number(cls);

    if (c >= 1 && c <= 5)
      return { development: 0, transport: 0 };

    if (c >= 6 && c <= 9)
      return { tuition: 0, development: 0, transport: 0 };

    return { exam: 0, tuition: 0, development: 0 };
  };

  // Fetch list of students
  const fetchStudents = async () => {
    try {
      const res = await axios.get("http://localhost:5000/api/fees/admin/students");
      setStudents(res.data.data || []);
    } catch (err) {
      console.error(err);
      toast.error("Failed to load students");
    }
  };

  useEffect(() => {
    fetchStudents();
  }, []);

  // When clicking a student
  const loadStudentFees = async (stu) => {
    setSelected(stu);

    try {
      const res = await axios.get(
        `http://localhost:5000/api/fees/student/${stu.admissionNo}`
      );

      if (!res.data.success) {
        toast.error("Failed to load fee details.");
        return;
      }

      const studentClass = stu.classApplied || stu.class;

      // backend returns merged structure
      const mergedFees = res.data.data.fee;

      setFeeData(mergedFees);

      // payments (optional)
      const payments = res.data.data.payments || [];
      const paidAmount = payments.reduce((s, p) => s + (p.amount || 0), 0);

      const totalAmount = Object.values(mergedFees).reduce((s, v) => s + v, 0);

      setPaid(paidAmount);
      setTotal(totalAmount);
      setRemaining(totalAmount - paidAmount);
    } catch (err) {
      console.error(err);
      toast.error("Error fetching fee details");
    }
  };

  // Update value
  const updateAmount = (key, value) => {
    const num = Number(value) || 0;

    setFeeData((prev) => {
      const updated = { ...prev, [key]: num };
      const totalAmount = Object.values(updated).reduce((s, v) => s + v, 0);
      setTotal(totalAmount);
      setRemaining(totalAmount - paid);
      return updated;
    });
  };

  // Add new fee type
  const addFeeType = () => {
    const key = prompt("Enter new fee type (e.g., library, dance):");

    if (!key) return;
    if (feeData[key]) return toast.error("Fee type already exists!");

    setFeeData((prev) => ({
      ...prev,
      [key]: 0,
    }));
  };

  // Delete a fee type
  const deleteFeeType = (key) => {
    if (!window.confirm(`Delete fee type "${key}"?`)) return;

    setFeeData((prev) => {
      const updated = { ...prev };
      delete updated[key];

      const totalAmount = Object.values(updated).reduce((s, v) => s + v, 0);
      setTotal(totalAmount);
      setRemaining(totalAmount - paid);

      return updated;
    });
  };

  // Save changes to backend
  const saveChanges = async () => {
    if (!selected) return;

    try {
      const res = await axios.post(
        "http://localhost:5000/api/fees/student",
        {
          admissionNo: selected.admissionNo,
          feeOverrides: feeData,
        }
      );

      if (res.data.success) {
        toast.success("Changes saved successfully!");
      } else {
        toast.error(res.data.error || "Failed to save changes");
      }
    } catch (err) {
      console.error(err);
      toast.error("Error saving changes");
    }
  };

  return (
    <div className="admin-fees-page">
      <Toaster />
      <h2 className="admin-fee-title">Manage Student Fees</h2>

      <div className="admin-fee-grid">
        {/* Student List */}
        <div className="student-list">
          <h3 className="section-title">Students</h3>

          {students.length === 0 && <p>No students found.</p>}

          <ul>
            {students.map((stu) => (
              <li
                key={stu._id}
                onClick={() => loadStudentFees(stu)}
                className={selected?._id === stu._id ? "selected" : ""}
              >
                <b>{stu.studentName}</b> ({stu.admissionNo})
              </li>
            ))}
          </ul>
        </div>

        {/* Fee Editor */}
        <div className="fee-editor">
          {!selected ? (
            <p>Select a student to edit fee structure.</p>
          ) : (
            <>
              <h3 className="section-title">
                Edit Fees — {selected.studentName} (Class {selected.classApplied})
              </h3>

              <button className="add-fee-btn" onClick={addFeeType}>
                + Add Fee Type
              </button>

              <table className="fee-table">
                <thead>
                  <tr>
                    <th>Fee Type</th>
                    <th>Amount (₹)</th>
                  </tr>
                </thead>

                <tbody>
                  {Object.entries(feeData).map(([key, val]) => (
                    <tr key={key}>
                      <td>
                        {key}
                        <FontAwesomeIcon
                          icon={faTrash}
                          style={{
                            color: "crimson",
                            marginLeft: 10,
                            cursor: "pointer",
                          }}
                          onClick={() => deleteFeeType(key)}
                          title="Delete fee type"
                        />
                      </td>
                      <td>
                        <input
                          type="number"
                          value={val}
                          onChange={(e) => updateAmount(key, e.target.value)}
                        />
                      </td>
                    </tr>
                  ))}

                  <tr className="fee-total">
                    <td><b>Total</b></td>
                    <td><b>₹{total}</b></td>
                  </tr>

                  <tr>
                    <td>Paid</td>
                    <td>₹{paid}</td>
                  </tr>

                  <tr>
                    <td>Remaining</td>
                    <td>₹{remaining}</td>
                  </tr>
                </tbody>
              </table>

              <button className="ad-stu-fee-save-btn" onClick={saveChanges}>
                Save Changes
              </button>
            </>
          )}
        </div>
      </div>
    </div>
  );
}
